             ReadonlyState::Done{op, ret, node_id, version_upper_bound } => {
                 &&& self.wf_node_id(node_id)
                 &&& version_upper_bound <= self.version_upper_bound
                 &&& version_upper_bound <= self.current_local_version(node_id)
